for a in range(16): train.append([[a,99]])
for b in range(16): train.append([[99,b]])
# First run no active to inspect rules
job={'fields':fields,'slots':K,'predicates':preds,'width':4,'train':train,'approved':[],'queries':[]}
st=time.time();r=compile_job(job);print('discover',time.time()-st,'rules',len(r['rules']),r['rules'][:2],r['rules'][-2:])
# Approved 256 rules sampled/picked first
appr=[x['clause'] for x in r['rules'][:256]]
# queries: unique fixed values and target prefixes
queries=[]
for i in range(64):
 t=rng.choice(['x','y'])
 fixed=[]
 # include one fixed on other field sometimes
 if rng.random()<.7:
  fixed=[{'ref':[0,'y' if t=='x' else 'x'],'value':rng.choice(list(range(16))+[99])}]
 for j in range(rng.randrange(3)):
  # can't duplicate; skip
  pass
 pref=''.join(str(rng.randrange(10)) for _ in range(rng.randrange(8)))
 queries.append({'fixed':fixed,'target':[0,t],'prefix':pref})
job['approved']=appr;job['queries']=queries
