# oracle decode brute use compile world manually
worlds=[]
for x in fields[0]['domain']:
 for y in fields[1]['domain']:worlds.append((x,y))
# evaluate preds direct
def truth(p,w):
 rel='x' if p['left']['ref'][1]=='x' else 'y';v=w[0 if rel=='x' else 1];c=p['right']['const'];return v!=c
active=set(tuple(c) for c in appr)
arules=[x for x in r['rules'] if tuple(x['clause']) in active]
ans=[]
for q in queries:
 comps=[]
 for wi,w in enumerate(worlds):
  vals={'x':w[0],'y':w[1]}
  ok=all(vals[b['ref'][1]]==b['value'] for b in q['fixed'])
  if not ok:continue
  for rr in arules:
   if not any(truth(preds[p],w) for p in rr['clause']):ok=False;break
  if not ok:continue
  s=str(vals[q['target'][1]])
  if s.startswith(q['prefix']):comps.append((wi,s))
 if not comps:a={'count':0,'tokens':[],'witness':None}
 else:
  pre=q['prefix'];ds=set();end=False
  for wi,s in comps:
   if len(s)==len(pre):end=True
   else:ds.add(s[len(pre)])
  a={'count':len(comps),'tokens':[str(d) for d in range(10) if str(d) in ds]+(['END'] if end else []),'witness':min(wi for wi,s in comps)}
 ans.append(a)
print('answers match',ans==r2['answers'])
if ans!=r2['answers']:
 print(ans);print(r2['answers'])
